// Samme equirektangulære projeksjon som ble brukt på banene over.
// Gir piksel-posisjon i [0,KART_BREDDE] × [0,KART_HOEYDE] for lng/lat.
const LNG_MIN = -26, LAT_MAX = 71
const COS0 = 0.6156614753256583, SX = 22.796761340108688
export function projiser(lng: number, lat: number): { x: number; y: number } {
  return { x: (lng - LNG_MIN) * COS0 * SX, y: (LAT_MAX - lat) * SX }
}
